// 本插件想法来源由“验证码ocr识别”、“显示url图片或者base64图片”两个插件提供，感谢两位
yakit.AutoInitYakit()
# Input your code!

getcode_req = cli.Text("get_captcha",cli.setRequired(true),cli.setHelp("输入获取验证码的完整请求包"))

image_key = cli.String("keyword", cli.setRequired(true),cli.setHelp("输入验证码字典的关键字"))

repeat_time = cli.Int("repeat_num",cli.setRequired(true),cli.setHelp("重复次数"))

orc_req = cli.Text("ocr_req",cli.setRequired(true),cli.setHelp("输入ocr服务的请求包,不包括请求体"))
/*本插件默认使用的captcha-killer的ocr识别接口codereg.py，OCR接口请求样例
POST /reg HTTP/1.1
Host: 127.0.0.1:8888
Authorization: Basic f0ngauth
*/
cli.check()

// 重复指定次数
for i = 0;i<repeat_time;i++ {
    // 发送请求，获取验证码图片二进制数据，是否发送https由poc.https()控制
    rsp1, req1 = poc.HTTP(getcode_req,poc.https(true))~

    // 处理数据格式，获取验证码base64图片
    RawImage = poc.GetHTTPPacketBody(rsp1 /*type: []byte*/)
    // 此处是对拿到的请求体做数据处理，可根据应用的实际响应包数据结构进行调整
    respJson = json.loads(string(RawImage))
    image_data = respJson["data"][image_key]
    //uuid1 = respJson["data"]["uuid"]

    // 将验证图片放入请求体，发给 OCR服务 识别
    rsp2, req2 = poc.HTTP(orc_req, poc.replaceBody(image_data  /*type: []byte*/, false /*type: bool*/))~

    // 获取返回的ocr识别结果
    captcha = poc.GetHTTPPacketBody(rsp2 /*type: []byte*/)
    capt_result = string(captcha)
    
    // 以markdown格式在插件的“日志”展示验证码图片和识别结果
    base64_url = "data:image/png;base64,%v"
    mark_image = "![图片](%v)  <font size=7>%v</font>"
    image_url = str.f(base64_url,image_data)
    yakit.Markdown(str.f(mark_image,image_url,capt_result))

}
